from author import page,section as s
page('artisense','en','overview','ArtiSense. Reading the world through light.','Explore ArtiSense, a proposed miniaturized photonic chemical-sensing system: architecture, glucose-design research, limitations and the next validation questions.','ARTISENSE / OVERVIEW','A research direction in chemical sensing: illuminate a sample, observe its optical response, and explore what that signal can tell us.',[
s('purpose','A smaller system. A demanding measurement problem.','ArtiSense aims to connect photonic sensing with signal interpretation in a miniaturized system. Non-invasive measurement and wearable formats are intended directions, rather than demonstrated product capabilities.','The central challenge is not just to detect light. It is to show that a response reliably corresponds to the substance of interest under the conditions in which a device would be used. Intended users and useful operating limits must follow that evidence.',links=['artisense-applications']),
s('system','The proposed system, at a glance.','The described architecture links visible or infrared illumination, interaction with a sample, detection of the optical response, and comparison with a reference. Interpretation would turn the resulting spectral information into a meaningful measurement.','A reprogrammable analog neuromorphic processor, software support and connectivity appear in the proposed architecture. Their description is not evidence that each block has been built and integrated. The analog interpretation processor is separate from AIFIELD’s neural optical-field research.',links=['artisense-technology']),
s('stage','What the work currently supports.','The supplied research summary describes optical feasibility and photonic glucose chip-design work. AIFIELD provides a relevant context for explaining that design activity.','Design and simulation can help choose the next experiment. They do not establish fabricated-device performance, glucose accuracy, clinical outcomes or a ready-to-use wearable.',rows=[['Available basis','Optical feasibility and chip-design work in the supplied research summary.'],['Open validation','A controlled physical response, reproducibility and separation from interfering effects.'],['Next useful milestone','Define a measurable hypothesis and the reference comparison needed to test it.']],links=['artisense-validation','aifield-validation']),
s('next','Explore the system. Then examine the evidence.','Technology explains the proposed signal chain. Applications explains the intended measurement context. Research and Validation separates what design work supports from the experiments still needed.','Investment conversations concern Artifactory as a company. Potential technical collaborations can focus on optical characterization, integration or a carefully bounded validation study.',links=['artisense-technology','artisense-applications','artisense-validation','investors','partnerships'])],['artisense-technology','artisense-applications','artisense-validation','investors','partnerships'],project='artisense',visual='sensing',maturity='Proposed sensing system · research')
page('artisense','pl','overview','ArtiSense. Poznawać świat dzięki światłu.','Poznaj ArtiSense, proponowany miniaturowy system fotonicznych pomiarów chemicznych: architekturę, projekt glukozowy, ograniczenia i dalszą walidację.','ARTISENSE / PRZEGLĄD','Kierunek badań nad pomiarem składu chemicznego: oświetlić próbkę, zarejestrować odpowiedź optyczną i sprawdzić, co może powiedzieć nam ten sygnał.',[
s('purpose','Mniejszy system. Wymagające zadanie pomiarowe.','ArtiSense ma łączyć pomiary fotoniczne z interpretacją sygnału w zminiaturyzowanym systemie. Pomiary nieinwazyjne i formy ubieralne to zamierzone kierunki, a nie wykazane możliwości produktu.','Główne wyzwanie nie polega jedynie na wykryciu światła. Trzeba pokazać, że odpowiedź wiarygodnie odpowiada badanej substancji w warunkach używania urządzenia. Docelowi użytkownicy i użyteczny zakres pracy muszą wynikać z tych dowodów.',links=['artisense-applications']),
s('system','Proponowany system w skrócie.','Opisana architektura łączy oświetlenie widzialne lub podczerwone, oddziaływanie z próbką, detekcję odpowiedzi optycznej i porównanie z odniesieniem. Interpretacja miałaby przekształcać informację widmową w znaczący pomiar.','W proponowanej architekturze pojawia się przeprogramowywalny analogowy procesor neuromorficzny, oprogramowanie i łączność. Sam opis nie dowodzi wykonania i integracji każdego bloku. Analogowy procesor interpretacji jest czymś innym niż badania neuronowego pola optycznego w AIFIELD.',links=['artisense-technology']),
s('stage','Co potwierdza obecny zakres prac.','Dostarczone podsumowanie badań opisuje wykonalność optyczną i projektowanie fotonicznego chipu związanego z glukozą. AIFIELD stanowi kontekst dla wyjaśnienia tych działań projektowych.','Projekt i symulacja mogą pomóc wybrać kolejny eksperyment. Nie potwierdzają parametrów wykonanego urządzenia, dokładności pomiaru glukozy, wyników klinicznych ani gotowego rozwiązania ubieralnego.',rows=[['Dostępna podstawa','Prace nad wykonalnością optyczną i projektem chipu opisane w podsumowaniu badań.'],['Otwarta walidacja','Kontrolowana odpowiedź fizyczna, powtarzalność i oddzielenie wpływów zakłócających.'],['Kolejny użyteczny krok','Określenie mierzalnej hipotezy i porównania odniesienia potrzebnego do jej sprawdzenia.']],links=['artisense-validation','aifield-validation']),
s('next','Poznaj system. Następnie sprawdź dowody.','Technologia wyjaśnia proponowany tor sygnałowy. Zastosowania opisują zamierzony kontekst pomiaru. Badania i walidacja oddzielają to, co wynika z projektu, od potrzebnych eksperymentów.','Rozmowy inwestycyjne dotyczą Artifactory jako firmy. Potencjalna współpraca techniczna może skupić się na charakteryzacji optycznej, integracji lub precyzyjnie określonym badaniu walidacyjnym.',links=['artisense-technology','artisense-applications','artisense-validation','investors','partnerships'])],['artisense-technology','artisense-applications','artisense-validation','investors','partnerships'],project='artisense',visual='sensing',maturity='Proponowany system pomiarowy · badania')
